const app=express();app.set('trust proxy',1);app.use(helmet());app.use(cors({origin:(env.CORS_ORIGIN||'').split(',').map(x=>x.trim()),credentials:true}));app.use(express.json({limit:'12mb'}));app.use(rateLimit({windowMs:60_000,limit:120,standardHeaders:true,legacyHeaders:false}));
app.use((req,res,next)=>{if(req.path.startsWith('/api/')&&!['GET','HEAD','OPTIONS'].includes(req.method)){const origin=req.get('origin');const allowed=new Set([env.FRONTEND_URL,...(env.CORS_ORIGIN||'').split(',')].filter(Boolean).map(x=>x.trim().replace(/\/$/,'')));if(origin&&allowed.size&&!allowed.has(origin))return res.status(403).json({error:{code:'ORIGIN_FORBIDDEN'}})}next()});
