function issueSession(user,res){const token=jwt.sign({sub:String(user._id),role:user.role},env.JWT_SECRET,{expiresIn:'2h',issuer:'smokeisland-api',audience:'smokeisland-web'});res.cookie('si_session',token,{httpOnly:true,secure:env.NODE_ENV==='production',sameSite:'lax',maxAge:2*60*60*1000,path:'/'});return token}
async function requireUser(req,res,next){try{const token=req.cookies?.si_session||req.get('authorization')?.replace(/^Bearer /,'');if(!token)return res.status(401).json({error:{code:'UNAUTHORIZED'}});const claims=jwt.verify(token,env.JWT_SECRET,{issuer:'smokeisland-api',audience:'smokeisland-web',algorithms:['HS256']});const user=await User.findById(claims.sub);if(!user||user.status!=='ACTIVE')return res.status(401).json({error:{code:'UNAUTHORIZED'}});req.user=user;next()}catch{return res.status(401).json({error:{code:'UNAUTHORIZED'}})}}
async function optionalUser(req,res,next){try{const token=req.cookies?.si_session||req.get('authorization')?.replace(/^Bearer /,'');if(token){const claims=jwt.verify(token,env.JWT_SECRET,{issuer:'smokeisland-api',audience:'smokeisland-web',algorithms:['HS256']});req.user=await User.findOne({_id:claims.sub,status:'ACTIVE'})}}catch{}next()}
const roleRank={USER:0,MANAGER:1,ADMIN:2,SUPER_ADMIN:3};
function requireRole(min){return (req,res,next)=>roleRank[req.user?.role]>=roleRank[min]?next():res.status(403).json({error:{code:'FORBIDDEN'}})}
const asyncRoute=fn=>(req,res,next)=>Promise.resolve(fn(req,res,next)).catch(next);
const cookieParser=(req,res,next)=>{req.cookies={};for(const part of (req.headers.cookie||'').split(';')){const i=part.indexOf('=');if(i<0)continue;try{req.cookies[part.slice(0,i).trim()]=decodeURIComponent(part.slice(i+1))}catch{}}next()};app.use(cookieParser);
app.use('/api/v1',async(req,res,next)=>{let key=req.cookies.si_visitor;if(!key||!/^[A-Za-z0-9_-]{32,80}$/.test(key)){key=nodeCrypto.randomBytes(32).toString('base64url');res.cookie('si_visitor',key,{httpOnly:true,secure:env.NODE_ENV==='production',sameSite:'lax',maxAge:365*24*60*60*1000,path:'/'});}req.visitorKey=key;const ref=typeof req.query.ref==='string'?req.query.ref:typeof req.body?.referralCode==='string'?req.body.referralCode:null;if(ref&&/^[A-Za-z0-9_-]{4,32}$/.test(ref)){req.referralCode=ref;res.cookie('si_referral',ref,{httpOnly:true,secure:env.NODE_ENV==='production',sameSite:'lax',maxAge:90*24*60*60*1000,path:'/'});}try{const hasSession=Boolean(req.cookies.si_session||req.get('authorization'));if(!hasSession)req.guestUser=await ensureGuest(req);next()}catch(e){next(e)}});
const smartPriceMinor=quantity=>(quantity>=100?40:quantity>=50?45:quantity>=20?48:quantity>=10?55:quantity>=5?60:quantity>=3?65:70)*100;
function earnedPointsForOrder(order){return Math.floor(Math.max(0,Number(order.totalMinor||0))*3/10000)}
const tokenHash=value=>nodeCrypto.createHash('sha256').update(String(value)).digest('hex');
const referralCode=()=>nodeCrypto.randomBytes(6).toString('base64url').replace(/[-_]/g,'').slice(0,8).toUpperCase();
async function createUser(data){for(let n=0;n<5;n++){try{return await User.create({...data,referralCode:data.referralCode||referralCode()})}catch(e){if(e.code!==11000||!String(e.message).includes('referralCode'))throw e}}throw new Error('REFERRAL_CODE_EXHAUSTED')}
async function referrerFromCookie(req){const code=req.referralCode||req.cookies?.si_referral;if(!code)return undefined;return (await User.findOne({referralCode:code,isGuest:false}).select('_id'))?._id}
async function ensureReferralRecord(user,session){if(!user?.referredBy||String(user.referredBy)===String(user._id))return null;const referrer=await User.findById(user.referredBy).select('referralCode').session(session||null);if(!referrer)return null;const update={$set:{referrer:referrer._id,referralCode:referrer.referralCode},$setOnInsert:{invitee:user._id,createdAt:user.createdAt||new Date()}};if(user.referralPurchaseQualified){update.$set.purchaseQualified=true;update.$min={purchasedAt:user.updatedAt||new Date()}}return Referral.findOneAndUpdate({invitee:user._id},update,{upsert:true,new:true,setDefaultsOnInsert:true,session})}
async function syncReferralRecordsForReferrer(referrerId,session){const invitees=await User.find({referredBy:referrerId}).select('_id referredBy referralPurchaseQualified createdAt updatedAt').session(session||null).lean();if(!invitees.length)return;const referrer=await User.findById(referrerId).select('referralCode').session(session||null);if(!referrer)return;const operations=invitees.map(user=>({updateOne:{filter:{invitee:user._id},update:{$set:{referrer:referrerId,referralCode:referrer.referralCode,...(user.referralPurchaseQualified?{purchaseQualified:true}:{})},...(user.referralPurchaseQualified?{$min:{purchasedAt:user.updatedAt||user.createdAt||new Date()}}:{}),$setOnInsert:{invitee:user._id,createdAt:user.createdAt||new Date()}},upsert:true}}));await Referral.bulkWrite(operations,{...(session?{session}:{})})}
async function mergeReferralInvitee(fromId,toId,referrerId,purchaseQualified,session){const ids=[fromId,toId].filter(Boolean),rows=await Referral.find({invitee:{$in:ids}}).session(session||null);if(!referrerId||String(referrerId)===String(toId)){await Referral.deleteMany({invitee:{$in:ids}},{...(session?{session}:{})});return null}const matching=rows.filter(row=>String(row.referrer)===String(referrerId)),keep=matching.find(row=>String(row.invitee)===String(toId))||matching[0]||rows.find(row=>String(row.invitee)===String(toId))||rows[0],referrer=await User.findById(referrerId).select('referralCode').session(session||null);if(!referrer){await Referral.deleteMany({invitee:{$in:ids}},{...(session?{session}:{})});return null}if(keep){const duplicates=rows.filter(row=>row!==keep);if(duplicates.length)await Referral.deleteMany({_id:{$in:duplicates.map(row=>row._id)}},{...(session?{session}:{})});keep.invitee=toId;keep.referrer=referrerId;keep.referralCode=referrer.referralCode;if(matching.some(row=>row.purchaseQualified)||purchaseQualified){keep.purchaseQualified=true;keep.purchasedAt=matching.map(row=>row.purchasedAt).filter(Boolean).sort((a,b)=>a-b)[0]||keep.purchasedAt||new Date();keep.purchaseOrder??=matching.find(row=>row.purchaseOrder)?.purchaseOrder}keep.rewardGroup=matching.map(row=>row.rewardGroup).filter(Boolean).sort((a,b)=>a-b)[0]||keep.rewardGroup;keep.rewardedAt=matching.map(row=>row.rewardedAt).filter(Boolean).sort((a,b)=>a-b)[0]||keep.rewardedAt;await keep.save({...(session?{session}:{})});return keep}return Referral.create([{referrer:referrerId,invitee:toId,referralCode:referrer.referralCode,purchaseQualified:Boolean(purchaseQualified),...(purchaseQualified?{purchasedAt:new Date()}:{})}],session?{session}:{})}
async function moveUserLinks(fromId,toId,session){await Order.updateMany({owner:fromId},{$set:{owner:toId}},{session});await Ledger.updateMany({user:fromId},{$set:{user:toId}},{session});await BonusReward.updateMany({owner:fromId},{$set:{owner:toId}},{session});await Thread.updateMany({owner:fromId},{$set:{owner:toId}},{session});await Referral.updateMany({referrer:fromId},{$set:{referrer:toId}},{session});await User.updateMany({referredBy:fromId},{$set:{referredBy:toId}},{session})}
async function ensureGuest(req){let guest=await User.findOne({guestKey:req.visitorKey,isGuest:true});if(!guest)try{guest=await createUser({guestKey:req.visitorKey,isGuest:true,referredBy:await referrerFromCookie(req)})}catch(e){if(e.code!==11000)throw e;guest=await User.findOne({guestKey:req.visitorKey,isGuest:true})}if(guest?.referredBy)await ensureReferralRecord(guest);return guest}
async function mergeGuestData(user,visitorKey){if(!visitorKey)return user;const session=await mongoose.startSession();try{await session.withTransaction(async()=>{const current=await User.findById(user._id).session(session),guest=await User.findOne({guestKey:visitorKey,isGuest:true}).session(session);if(!current)return;if(guest&&String(guest._id)!==String(current._id))await moveUserLinks(guest._id,current._id,session);if(current.email)await Order.updateMany({owner:null,'contact.email':new RegExp('^'+current.email.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'$','i')},{$set:{owner:current._id}},{session});if(current.telegramId)await Thread.updateMany({owner:null,telegramId:current.telegramId},{$set:{owner:current._id}},{session});if(!guest||String(guest._id)===String(current._id)){await current.save({session});await ensureReferralRecord(current,session);user=current;return;}current.points=(current.points||0)+(guest.points||0);if(String(current.referredBy||'')===String(guest._id))current.referredBy=guest.referredBy&&String(guest.referredBy)!==String(current._id)?guest.referredBy:undefined;if(!current.referredBy&&guest.referredBy&&String(guest.referredBy)!==String(current._id))current.referredBy=guest.referredBy;const sameInviter=String(current.referredBy||'')===String(guest.referredBy||'');if(!current.referralPurchaseQualified&&sameInviter&&guest.referralPurchaseQualified)current.referralPurchaseQualified=true;current.referralPairsAwarded=Math.max(current.referralPairsAwarded||0,guest.referralPairsAwarded||0);if(!current.firstName)current.firstName=guest.firstName;if(!current.lastName)current.lastName=guest.lastName;await current.save({session});await mergeReferralInvitee(guest._id,current._id,current.referredBy,current.referralPurchaseQualified,session);await User.deleteOne({_id:guest._id},{session});user=current})}finally{await session.endSession()}return user}
async function mergeIdentity(user,identity){if(user[identity.key]&&user[identity.key]!==identity.value)throw Object.assign(new Error('IDENTITY_CONFLICT'),{status:409});const session=await mongoose.startSession();try{await session.withTransaction(async()=>{const current=await User.findById(user._id).session(session),other=await User.findOne({[identity.key]:identity.value}).session(session);if(!current)throw Object.assign(new Error('UNAUTHORIZED'),{status:401});if(other&&String(other._id)!==String(current._id)){if(other.email&&current.email&&other.email.toLowerCase()!==current.email.toLowerCase()||(other.googleId&&current.googleId&&other.googleId!==current.googleId)||(other.telegramId&&current.telegramId&&other.telegramId!==current.telegramId))throw Object.assign(new Error('IDENTITY_CONFLICT'),{status:409});if(String(current.referredBy||'')===String(other._id))current.referredBy=other.referredBy&&String(other.referredBy)!==String(current._id)?other.referredBy:undefined;if(!current.email)current.email=other.email;if((roleRank[other.role]||0)>(roleRank[current.role]||0))current.role=other.role;if(!current.googleId)current.googleId=other.googleId;if(!current.telegramId)current.telegramId=other.telegramId;if(!current.username)current.username=other.username;if(!current.firstName)current.firstName=other.firstName;if(!current.lastName)current.lastName=other.lastName;if(!current.referredBy&&other.referredBy&&String(other.referredBy)!==String(current._id))current.referredBy=other.referredBy;const sameInviter=String(current.referredBy||'')===String(other.referredBy||'');if(!current.referralPurchaseQualified&&sameInviter&&other.referralPurchaseQualified)current.referralPurchaseQualified=true;current.referralPairsAwarded=Math.max(current.referralPairsAwarded||0,other.referralPairsAwarded||0);current.points=(current.points||0)+(other.points||0);await moveUserLinks(other._id,current._id,session);await User.deleteOne({_id:other._id},{session});await mergeReferralInvitee(other._id,current._id,current.referredBy,current.referralPurchaseQualified,session)}current[identity.key]=identity.value;await current.save({session});await ensureReferralRecord(current,session);user=current})}finally{await session.endSession()}return user}

const otpDigest=(email,code)=>nodeCrypto.createHmac('sha256',env.SESSION_SECRET).update(`${email}:${code}`).digest('hex');
async function attachReferral(user,code){if(!user.referredBy&&code&&code!==user.referralCode){const ref=await User.findOne({referralCode:code,isGuest:false}).select('_id');if(ref&&String(ref._id)!==String(user._id)){user.referredBy=ref._id;await user.save()}}if(user.referredBy)await ensureReferralRecord(user);return user}
async function awardReferralPair(ownerId,orderId,session){const buyer=await User.findById(ownerId).session(session);if(!buyer?.referredBy)return;if(!buyer.referralPurchaseQualified){buyer.referralPurchaseQualified=true;await buyer.save({session})}const referral=await ensureReferralRecord(buyer,session);if(!referral)return;referral.purchaseQualified=true;referral.purchasedAt??=new Date();referral.purchaseOrder??=orderId;await referral.save({session});const referrerId=buyer.referredBy;await syncReferralRecordsForReferrer(referrerId,session);const purchased=await Referral.find({referrer:referrerId,purchaseQualified:true}).sort({purchasedAt:1,createdAt:1,_id:1}).session(session);for(let index=0;index<purchased.length;index++){const row=purchased[index],group=Math.floor(index/2)+1;if(index%2===0&&index+1>=purchased.length)continue;if(row.rewardGroup!==group||!row.rewardedAt){row.rewardGroup=group;row.rewardedAt??=new Date();await row.save({session})}}const pairs=Math.floor(purchased.length/2),referrer=await User.findById(referrerId).session(session);if(!referrer)return;while((referrer.referralPairsAwarded||0)<pairs){const pair=(referrer.referralPairsAwarded||0)+1;referrer.points+=10;referrer.referralPairsAwarded=pair;await Ledger.create([{user:referrer._id,amount:10,reason:'Referral pair completed',operationKey:`referral-pair:${referrer.id}:${pair}`}],{session})}await referrer.save({session})}

async function sendEmailCode(email,code){if(!env.RESEND_API_KEY||!env.EMAIL_FROM)throw Object.assign(new Error('EMAIL_NOT_CONFIGURED'),{status:503});const response=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:`Bearer ${env.RESEND_API_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({from:env.EMAIL_FROM,to:[email],subject:'Potwierdź swój e-mail · Smoke Island',html:`<div style="font-family:Arial,sans-serif;background:#061225;color:#fff;padding:32px;border-radius:16px"><h1>Potwierdź swój e-mail</h1><p>Twój 6-cyfrowy kod:</p><strong style="font-size:32px;letter-spacing:10px;color:#38a5ff">${code}</strong><p>Kod wygaśnie za 10 minut. Jeśli to nie Ty, zignoruj wiadomość.</p></div>`})});if(!response.ok){console.error('email provider error',response.status);throw Object.assign(new Error('EMAIL_DELIVERY_FAILED'),{status:502})}}
function validSupportToken(thread,token){if(!thread.publicTokenHash||!token)return false;const actual=Buffer.from(tokenHash(token));const expected=Buffer.from(thread.publicTokenHash);return actual.length===expected.length&&nodeCrypto.timingSafeEqual(actual,expected)}
