app.post('/api/v1/bonus/rewards/:id/redeem',requireUser,asyncRoute(async(req,res)=>{if(!mongoose.isValidObjectId(req.params.id))return res.status(404).end();const result=await inventory.transaction(async session=>{const reward=await BonusReward.findOne({_id:req.params.id,owner:req.user._id}).session(session);if(!reward)throw Object.assign(Error('NOT_FOUND'),{status:404});if(!['%','pkt','discount'].includes(reward.rewardUnit))throw Object.assign(Error('BONUS_REWARD_INVALID'),{status:409});const code='BONUS-'+reward.id.toUpperCase();if(reward.status!=='REDEEMED'){if(reward.status!=='CLAIMED')throw Object.assign(Error('BONUS_REWARD_INVALID'),{status:409});if(reward.rewardUnit==='pkt'){await User.updateOne({_id:req.user._id},{$inc:{points:reward.rewardValue}},{session});await Ledger.create([{user:req.user._id,amount:reward.rewardValue,reason:'bonus-prize',operationKey:'prize:'+reward.id}],{session})}else await Promo.create([{code,percent:reward.rewardUnit==='%'?reward.rewardValue:undefined,owner:req.user._id,amountMinor:reward.rewardUnit==='discount'?Math.round(reward.rewardValue*100):0,singleUse:true,active:true,expiresAt:new Date(Date.now()+90*86400000)}],{session});reward.status='REDEEMED';await reward.save({session})}return {percent:reward.rewardUnit==='%'?reward.rewardValue:undefined,amountMinor:reward.rewardUnit==='discount'?Math.round(reward.rewardValue*100):undefined,unit:reward.rewardUnit,code:['%','discount'].includes(reward.rewardUnit)?code:undefined,points:(await User.findById(req.user._id).session(session)).points}});res.json(result)}));
const orderInput=z.object({promoCode:z.string().trim().max(40).optional(),referralCode:z.string().optional(),items:z.array(z.object({slug:z.string(),variantKey:z.string(),quantity:z.number().int().min(1).max(999),bonusRewardId:z.string().optional()})).min(1).max(100),contact:z.object({name:z.string().trim().min(2).max(160),email:z.preprocess(value=>value===''?undefined:value,z.email().optional()),phone:z.string().trim().min(7).max(30),city:z.string().trim().min(2).max(100),address:z.string().trim().min(2).max(300),comment:z.string().max(1000).optional()}),deliveryMethod:z.enum(['inpost','courier','zabka']),paymentMethod:z.enum(['manual']).default('manual')});
app.post('/api/v1/orders',optionalUser,asyncRoute(async(req,res)=>{const d=orderInput.parse(req.body),effectiveOwner=req.user||req.guestUser||await ensureGuest(req),idem=req.get('idempotency-key')?tokenHash(String(effectiveOwner._id)+':'+req.get('idempotency-key').slice(0,120)):'';await inventory.expire();await attachReferral(effectiveOwner,d.referralCode||req.cookies.si_referral||req.referralCode);if(idem){const old=await Order.findOne({idempotencyKey:idem});if(old)return res.status(200).json({number:old.number,status:old.status,totalMinor:old.totalMinor,telegramNotified:Boolean(old.telegramNotified)})}const quantityBySlug=new Map();for(const line of d.items)if(!line.bonusRewardId)quantityBySlug.set(line.slug,(quantityBySlug.get(line.slug)||0)+line.quantity);const session=await mongoose.startSession(),publicToken=nodeCrypto.randomBytes(32).toString('base64url');let order;const claimedRewards=[];try{await session.withTransaction(async()=>{const lines=[];const seenRewards=new Set();claimedRewards.length=0;let subtotal=0;const hold=await Hold.findOne({key:req.visitorKey}).session(session);if(hold)await inventory.release(hold,session);for(const line of d.items){if(line.bonusRewardId&&seenRewards.has(line.bonusRewardId))throw Object.assign(Error('BONUS_REWARD_INVALID'),{status:409});if(line.bonusRewardId)seenRewards.add(line.bonusRewardId);const reward=line.bonusRewardId?await BonusReward.findOne({_id:line.bonusRewardId,owner:effectiveOwner._id,status:'CLAIMED'}).session(session):null;if(line.bonusRewardId&&(!req.user||!reward||['%','pkt','discount'].includes(reward.rewardUnit)||line.quantity!==1||reward.productSlug!==line.slug||reward.variantKey!==line.variantKey))throw Object.assign(new Error('BONUS_REWARD_INVALID'),{status:409});const p=await Product.findOne({slug:line.slug,active:true}).session(session);if(!p)throw Object.assign(new Error('PRODUCT_UNAVAILABLE'),{status:409});const v=p.variants.find(x=>x.key===line.variantKey&&x.active);if(p.rewardOnly&&!reward)throw Object.assign(Error('BONUS_REWARD_INVALID'),{status:409});if(!v||(!p.rewardOnly&&available(v)<line.quantity))throw stockError(p,v);if(!p.rewardOnly)v.reserved=(v.reserved||0)+line.quantity;await p.save({session});const unitPriceMinor=reward?0:Math.min(v.priceMinor,smartPriceMinor(quantityBySlug.get(line.slug)));const amount=unitPriceMinor*line.quantity;subtotal+=amount;lines.push({productId:p._id,variantKey:v.key,name:p.name,variant:v.label,quantity:line.quantity,unitPriceMinor,lineTotalMinor:amount,...(reward?{bonusRewardId:reward._id}:{})});if(reward)claimedRewards.push(reward)}let discountMinor=0;if(d.promoCode){const promo=await Promo.findOne({code:d.promoCode.toUpperCase(),active:true,expiresAt:{$gt:new Date()}}).session(session);if(!promo||(promo.owner&&String(promo.owner)!==String(effectiveOwner._id)))throw Object.assign(Error('PROMO_INVALID'),{status:409});discountMinor=Math.min(subtotal,promo.percent?Math.floor(subtotal*promo.percent/100):promo.amountMinor);if(promo.singleUse){promo.active=false;promo.usedAt=new Date();await promo.save({session})}}const shippingMinor=subtotal>=95000?0:3000;const number='SKI-'+Date.now().toString(36).toUpperCase()+'-'+nodeCrypto.randomBytes(2).toString('hex').toUpperCase();const [created]=await Order.create([{number,idempotencyKey:idem||undefined,owner:effectiveOwner._id,publicTokenHash:nodeCrypto.createHash('sha256').update(publicToken).digest('hex'),contact:d.contact,items:lines,inventoryState:'reserved',promoCode:d.promoCode?.toUpperCase(),discountMinor,subtotalMinor:subtotal,shippingMinor,totalMinor:subtotal-discountMinor+shippingMinor,deliveryMethod:d.deliveryMethod,paymentMethod:d.paymentMethod,status:'PENDING_CONFIRMATION',events:[{status:'PENDING_CONFIRMATION',paymentStatus:'UNPAID',actor:String(effectiveOwner._id),note:'Order submitted'}]}],{session});order=created;for(const reward of claimedRewards){reward.status='ORDERED';reward.orderId=created._id;await reward.save({session})}})}finally{await session.endSession()}const markup=orderKeyboard(order);const summary=orderSummary(order);let telegramNotified=false;if(bot&&env.TELEGRAM_ORDERS_CHAT_ID){try{let sent;const parts=summary.match(/[\s\S]{1,3500}/g)||[''];for(let i=0;i<parts.length;i++)sent=await bot.telegram.sendMessage(env.TELEGRAM_ORDERS_CHAT_ID,parts[i],i===parts.length-1?markup:undefined);order.events.push({status:order.status,actor:'system',note:`Telegram notification ${sent.message_id}`});order.telegramNotified=true;await order.save();telegramNotified=true}catch(e){console.error('order notification failed',e.name)}}res.status(201).json({number:order.number,status:order.status,totalMinor:order.totalMinor,currency:'PLN',publicToken,telegramNotified})}));
