app.post('/api/v1/auth/email-code/verify',authLimiter,asyncRoute(async(req,res)=>{const d=z.object({code:z.string().regex(/^\d{6}$/)}).parse(req.body),challenge=req.cookies.si_email_challenge;if(!challenge)return res.status(401).json({error:{code:'EMAIL_CHALLENGE_EXPIRED'}});const pending=await PendingRegistration.findOne({challengeTokenHash:tokenHash(challenge),expiresAt:{$gt:new Date()}});if(!pending)return res.status(401).json({error:{code:'EMAIL_CHALLENGE_EXPIRED'}});if(pending.attempts>=5)return res.status(429).json({error:{code:'EMAIL_CODE_LOCKED'}});if(!nodeCrypto.timingSafeEqual(Buffer.from(pending.codeHash),Buffer.from(otpDigest(pending.email,d.code)))){pending.attempts++;await pending.save();return res.status(400).json({error:{code:'INVALID_EMAIL_CODE'}})}if(await User.exists({email:pending.email}))return res.status(409).json({error:{code:'ACCOUNT_EXISTS'}});let user=await createUser({email:pending.email,passwordHash:pending.passwordHash,firstName:pending.firstName,lastName:pending.lastName});await attachReferral(user,pending.referralCode);await mergeGuestData(user,req.visitorKey);await PendingRegistration.deleteOne({_id:pending._id});res.clearCookie('si_email_challenge',{path:'/'});res.clearCookie('si_referral',{path:'/'});issueSession(user,res);res.status(201).json({user:{id:user.id,email:user.email,firstName:user.firstName,lastName:user.lastName,points:user.points,referralCode:user.referralCode}})}));
