const bonusCaseCosts={Start:10,Premium:20,Exclusive:100};
async function caseProduct(tier,session){const query=q=>session?q.session(session):q;const configured=await query(Prize.findOne({tier}));if(configured)return query(Product.findOne({slug:configured.productSlug,active:true}));if(tier==='Start')return query(Product.findOne({slug:env.BONUS_REWARD_PRODUCT_SLUG||'bc',active:true}));const items=await query(Product.find({active:true,rewardOnly:{$ne:true}}));const eligible=items.filter(p=>p.variants.some(v=>v.active&&v.stock-(v.reserved||0)>0)).sort((a,b)=>Math.max(...a.variants.map(v=>v.priceMinor))-Math.max(...b.variants.map(v=>v.priceMinor))||a.slug.localeCompare(b.slug));return eligible.at(tier==='Exclusive'?-1:-2)||eligible.at(-1)}
