bot.action('menu:export',async ctx=>{const orders=await Order.find().sort({createdAt:-1}).limit(500).lean();const q=x=>`"${String(x??'').replace(/^[=+@-]/,"'$&").replaceAll('\"','\"\"')}"`;const csv=['number,status,payment_status,total_minor,created_at,customer,email,phone',...orders.map(o=>[o.number,o.status,o.paymentStatus,o.totalMinor,o.createdAt?.toISOString(),o.contact?.name,o.contact?.email,o.contact?.phone].map(q).join(','))].join('\n');await ctx.replyWithDocument({source:Buffer.from('\ufeff'+csv),filename:'orders.csv'});await ctx.answerCbQuery()});
