async function handleClientSupportMedia(ctx){if(!env.TELEGRAM_SUPPORT_CHAT_ID)return ctx.reply('Поддержка временно недоступна.');const photo=ctx.message.photo?.at(-1),doc=ctx.message.document;if(!photo&&!doc)return;const fileId=photo?.file_id||doc.file_id,mimeType=photo?'image/jpeg':doc.mime_type||'application/octet-stream',name=(doc?.file_name||`telegram-${Date.now()}.jpg`).replace(/[\/\\]/g,'_');if(!['image/jpeg','image/png','image/gif','image/webp','application/pdf','text/plain'].includes(mimeType))return ctx.reply('Отправьте изображение, PDF или текстовый файл.');const url=await ctx.telegram.getFileLink(fileId),download=await fetch(url);if(!download.ok)throw new Error('Telegram file download failed');const data=Buffer.from(await download.arrayBuffer());if(!data.length||data.length>2_000_000)return ctx.reply('Максимальный размер файла — 2 МБ.');let user=await User.findOne({telegramId:String(ctx.from.id),status:'ACTIVE'});if(!user)user=await createUser({telegramId:String(ctx.from.id),username:ctx.from.username,firstName:ctx.from.first_name||'Telegram',lastName:ctx.from.last_name||''});let thread=await Thread.findOne({$or:[{telegramId:String(ctx.from.id)},{owner:user._id}],status:'OPEN'});if(!thread)thread=await Thread.create({owner:user._id,telegramId:String(ctx.from.id),lastMessageAt:new Date()});else if(!thread.owner){thread.owner=user._id;await thread.save()}const message=await Message.create({thread:thread._id,senderRole:'CUSTOMER',senderId:String(ctx.from.id),text:(ctx.message.caption||'').slice(0,4000),attachments:[{name,mimeType,size:data.length,data}]});thread.lastMessageAt=new Date();await thread.save();try{const sent=await bot.telegram.sendMessage(env.TELEGRAM_SUPPORT_CHAT_ID,`Обращение #${thread.id}\nTelegram ID: ${ctx.from.id}\n${ctx.message.caption||'Вложение'}`);message.telegramMessageIds=[String(sent.message_id)];message.telegramMessageId=String(sent.message_id);await message.save();const forwarded=await bot.telegram.sendDocument(env.TELEGRAM_SUPPORT_CHAT_ID,{source:data,filename:name},{caption:`Вложение #${thread.id}`});message.telegramMessageIds.push(String(forwarded.message_id));await message.save();return ctx.reply('Вложение передано поддержке.')}catch(e){console.error('Telegram support media relay failed',e.name);return ctx.reply('Сообщение сохранено, но не удалось передать его поддержке.')}}
function makeClientBot(){const token=env.TELEGRAM_CLIENT_BOT_TOKEN;if(!token||token===env.TELEGRAM_ADMIN_BOT_TOKEN)return null;const client=new Telegraf(token);client.start(ctx=>ctx.reply('Добро пожаловать в Smoke Island. Откройте магазин кнопкой ниже.',env.TELEGRAM_WEB_APP_URL?Markup.keyboard([[{text:'Открыть магазин',web_app:{url:env.TELEGRAM_WEB_APP_URL}}]]).resize():undefined));client.on('text',async ctx=>{const text=ctx.message.text.trim();if(!text||text.startsWith('/'))return;if(!env.TELEGRAM_SUPPORT_CHAT_ID)return ctx.reply('Поддержка временно недоступна.');let user=await User.findOne({telegramId:String(ctx.from.id),status:'ACTIVE'});if(!user)user=await createUser({telegramId:String(ctx.from.id),username:ctx.from.username,firstName:ctx.from.first_name||'Telegram',lastName:ctx.from.last_name||''});let thread=await Thread.findOne({$or:[{telegramId:String(ctx.from.id)},{owner:user._id}],status:'OPEN'});if(!thread)thread=await Thread.create({owner:user._id,telegramId:String(ctx.from.id),lastMessageAt:new Date()});else if(!thread.owner){thread.owner=user._id;await thread.save()}const message=await Message.create({thread:thread._id,senderRole:'CUSTOMER',senderId:String(ctx.from.id),text:text.slice(0,4000)});thread.lastMessageAt=new Date();await thread.save();try{const sent=await bot.telegram.sendMessage(env.TELEGRAM_SUPPORT_CHAT_ID,`Обращение #${thread.id}\nTelegram ID: ${ctx.from.id}\n${text.slice(0,3500)}`);message.telegramMessageId=String(sent.message_id);await message.save();return ctx.reply('Сообщение передано поддержке. Ответ придёт сюда.')}catch(e){console.error('client support notification failed',e.name);return ctx.reply('Не удалось передать сообщение поддержке. Попробуйте позже.')}});client.on('photo',handleClientSupportMedia);client.on('document',handleClientSupportMedia);return client}
